// frontend/src/entities/match/api.ts
import { fetchMatches } from '@/shared/lib/axios';  // Импортируем именованный экспорт fetchMatches
import { Match } from './types';  // Импортируем тип Match

// Пример функции получения матчей
export const getLiveMatches = async (): Promise<Match[]> => {
  try {
    const data = await fetchMatches();
    return data;  // Возвращаем данные, полученные из fetchMatches
  } catch (err) {
    console.error('Ошибка при загрузке матчей:', err);
    return [];  // Если ошибка — возвращаем пустой массив
  }
};
